sys_script_include.script:
var LicenseAssignmentAjax = Class.create();

LicenseAssignmentAjax.prototype = Object.extendsObject(
    global.AbstractAjaxProcessor, {

        getLicense: function() {

            var assignmentId = this.getParameter(
                'sysparm_assignment_id'
            );

            var assignment = new GlideRecord(
                'x_1904737_smart_0_license_assignment'
            );

            if (assignment.get(assignmentId)) {

                return assignment.getValue('license');

            }

            return '';

        },

        type: 'LicenseAssignmentAjax'
    });
